  "glossary": [
    {
      "term": "Permit",
      "definition": "A licence the Environment Agency issues allowing a site to handle or treat waste under set conditions."
    },
    {
      "term": "Restriction order",
      "definition": "A court order that bans access to land so people cannot dump waste there while an investigation proceeds."
    },
    {
      "term": "Fixed penalty notice (FPN)",
      "definition": "A civil fine issued for lower-level offences (EA piloting these for on-the-spot waste violations)."
    },
    {
      "term": "Landfill tax",
      "definition": "A tax charged on waste sent to landfill which criminals avoid by misdeclaring waste type."
    },
    {
      "term": "HMRC",
      "definition": "Her Majesty’s Revenue and Customs — the government tax authority involved where tax evasion is suspected."
    },
    {
      "term": "National Crime Agency (NCA)",
      "definition": "The UK agency that leads on organised and serious crime and works with the EA on waste crime."
    },
    {
      "term": "MRF",
      "definition": "Material recovery facility — a waste transfer/processing site where waste can be diverted or resold."
    },
    {
      "term": "Digital waste tracking",
      "definition": "Electronic records of waste movements that the EA is beginning to analyse to detect suspicious flows."
    }
  ]
